  const accounts = new Map();
  for (const entry of entries) {
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry) ||
        typeof entry.member !== 'string' || entry.member.trim() === '' ||
        !Number.isInteger(entry.credits) || entry.credits < 0) {
      throw new TypeError('invalid entry');
    }
    const member = entry.member.trim();
    if (accounts.has(member)) throw new TypeError('duplicate member');
    accounts.set(member, { credits: entry.credits, lastTouch: 0 });
  }
  let day = 0;

  function requireMember(member) {
    if (typeof member !== 'string' || member.trim() === '' || !accounts.has(member.trim())) {
      throw new TypeError('unknown member');
    }
    return member.trim();
  }

  function requireLimit(limit) {
    if (!Number.isInteger(limit) || limit <= 0) throw new TypeError('invalid limit');
  }

  function overdue(limit) {
    requireLimit(limit);
    return Array.from(accounts.entries())
      .filter(([, account]) => day - account.lastTouch > limit)
      .map(([member]) => member)
      .sort();
  }

  return {
    advance(days) {
      if (!Number.isInteger(days) || days < 0) throw new TypeError('invalid days');
      day += days;
      return day;
    },
    touch(member) {
      const key = requireMember(member);
      accounts.get(key).lastTouch = day;
      return day;
    },
    overdue,
    redistribute(limit) {
      const late = overdue(limit);
      const lateSet = new Set(late);
      const active = Array.from(accounts.keys()).filter((name) => !lateSet.has(name)).sort();
      if (late.length === 0 || active.length === 0) return late;
      let pool = 0;
      for (const name of late) {
        pool += accounts.get(name).credits;
        accounts.get(name).credits = 0;
      }
      const share = Math.floor(pool / active.length);
      let remainder = pool % active.length;
      for (const name of active) {
        accounts.get(name).credits += share + (remainder > 0 ? 1 : 0);
        if (remainder > 0) remainder--;
      }
      return late;
    },
    balance(member) {
      return accounts.get(requireMember(member)).credits;
    }
  };
}

module.exports = { createLoanBook };

