'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createLoanBook']);
const { createLoanBook } = api;

const entries = [
  { member: '  Zoe  ', credits: 5 },
  { member: 'Amy', credits: 1 },
  { member: 'Moe', credits: 4 }
];
const snapshot = JSON.parse(JSON.stringify(entries));
const book = createLoanBook(entries);
assert.deepStrictEqual(entries, snapshot);
assert.strictEqual(book.balance(' Zoe '), 5);
assert.strictEqual(book.balance('Amy'), 1);
assert.deepStrictEqual(book.overdue(1), []);
assert.strictEqual(book.advance(2), 2);
assert.strictEqual(book.touch('Moe'), 2);
assert.deepStrictEqual(book.overdue(2), ['Amy', 'Zoe']);
assert.deepStrictEqual(book.redistribute(2), ['Amy', 'Zoe']);
assert.strictEqual(book.balance('Amy'), 0);
assert.strictEqual(book.balance('Zoe'), 0);
assert.strictEqual(book.balance('Moe'), 10);
assert.deepStrictEqual(book.redistribute(2), ['Amy', 'Zoe']);
assert.strictEqual(book.balance('Moe'), 10);

assert.strictEqual(book.advance(2), 4);
assert.deepStrictEqual(book.overdue(2), ['Amy', 'Moe', 'Zoe']);
assert.deepStrictEqual(book.redistribute(2), ['Amy', 'Moe', 'Zoe']);
assert.strictEqual(book.balance('Moe'), 10);

const split = createLoanBook([
  { member: 'D', credits: 5 },
  { member: 'B', credits: 0 },
  { member: 'A', credits: 0 },
  { member: 'C', credits: 0 }
]);
split.advance(3);
split.touch('C');
split.touch('A');
assert.deepStrictEqual(split.redistribute(2), ['B', 'D']);
assert.strictEqual(split.balance('A'), 3);
assert.strictEqual(split.balance('C'), 2);
assert.strictEqual(split.balance('B'), 0);
assert.strictEqual(split.balance('D'), 0);

const empty = createLoanBook([]);
assert.deepStrictEqual(empty.overdue(1), []);
assert.deepStrictEqual(empty.redistribute(1), []);
assert.strictEqual(empty.advance(0), 0);

for (const bad of [null, {}, 'x']) assert.throws(() => createLoanBook(bad), TypeError);
for (const bad of [
  [null], [{}], [{ member: '', credits: 1 }], [{ member: 'x', credits: -1 }],
  [{ member: 'x', credits: 1.5 }], [{ member: 'x', credits: NaN }],
  [{ member: ' x ', credits: 1 }, { member: 'x', credits: 2 }]
]) assert.throws(() => createLoanBook(bad), TypeError);
for (const value of [-1, 1.5, NaN, Infinity, '1']) assert.throws(() => book.advance(value), TypeError);
for (const value of [0, -1, 1.5, NaN, Infinity, '2']) {
  assert.throws(() => book.overdue(value), TypeError);
  assert.throws(() => book.redistribute(value), TypeError);
}
for (const member of ['', '   ', 'unknown', null]) {
  assert.throws(() => book.touch(member), TypeError);
  assert.throws(() => book.balance(member), TypeError);
}

